"use client";

import { useState, useEffect } from "react";
import { DoctorAppointment, getDoctorAppointments, updateAppointmentStatus } from "@/services/doctorService";

const STATUS_MAP: Record<string, { label: string; color: string; bg: string }> = {
    PENDING: { label: "Chờ xác nhận", color: "text-amber-700", bg: "bg-amber-50 border-amber-200" },
    CONFIRMED: { label: "Đã xác nhận", color: "text-blue-700", bg: "bg-blue-50 border-blue-200" },
    COMPLETED: { label: "Hoàn thành", color: "text-green-700", bg: "bg-green-50 border-green-200" },
    CANCELLED: { label: "Đã hủy", color: "text-red-700", bg: "bg-red-50 border-red-200" },
    RESCHEDULED: { label: "Đổi lịch", color: "text-purple-700", bg: "bg-purple-50 border-purple-200" },
};

const FILTER_OPTIONS = [
    { value: "ALL", label: "Tất cả" },
    { value: "PENDING", label: "Chờ xác nhận" },
    { value: "CONFIRMED", label: "Đã xác nhận" },
    { value: "COMPLETED", label: "Hoàn thành" },
    { value: "CANCELLED", label: "Đã hủy" },
];

export default function DoctorAppointments() {
    const [appointments, setAppointments] = useState<DoctorAppointment[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("ALL");
    const [updatingId, setUpdatingId] = useState<string | null>(null);

    useEffect(() => {
        fetchAppointments();
    }, []);

    const fetchAppointments = async () => {
        setLoading(true);
        try {
            const data = await getDoctorAppointments();
            setAppointments(data);
        } catch (error) {
            console.error("Failed to fetch doctor appointments:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleUpdateStatus = async (appointmentId: string, newStatus: string) => {
        setUpdatingId(appointmentId);
        try {
            await updateAppointmentStatus(appointmentId, newStatus);
            // Optimistic update
            setAppointments(prev =>
                prev.map(apt =>
                    apt.id === appointmentId ? { ...apt, appointmentStatus: newStatus } : apt
                )
            );
        } catch (error) {
            console.error("Failed to update appointment status:", error);
            alert("Cập nhật trạng thái thất bại. Vui lòng thử lại.");
        } finally {
            setUpdatingId(null);
        }
    };

    const filteredAppointments = filter === "ALL"
        ? appointments
        : appointments.filter(a => a.appointmentStatus === filter);

    const formatDate = (dateStr: string) => {
        try {
            return new Date(dateStr).toLocaleDateString('vi-VN', {
                weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric'
            });
        } catch { return dateStr; }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
    };

    if (loading) {
        return (
            <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-soft">
                <div className="flex items-center gap-3 mb-4">
                    <span className="text-2xl">🩺</span>
                    <h2 className="text-lg font-bold text-slate-900">Quản lý ca khám</h2>
                </div>
                <div className="flex items-center justify-center py-12">
                    <div className="h-8 w-8 animate-spin rounded-full border-4 border-dermcare border-t-transparent"></div>
                    <span className="ml-3 text-sm text-slate-500">Đang tải lịch hẹn...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-soft" id="appointments">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-5">
                <div className="flex items-center gap-3">
                    <span className="text-2xl">🩺</span>
                    <div>
                        <h2 className="text-lg font-bold text-slate-900">Quản lý ca khám</h2>
                        <p className="text-sm text-slate-500">{appointments.length} lịch hẹn</p>
                    </div>
                </div>

                {/* Filter */}
                <div className="flex gap-2 flex-wrap">
                    {FILTER_OPTIONS.map(opt => (
                        <button
                            key={opt.value}
                            onClick={() => setFilter(opt.value)}
                            className={`rounded-full px-3 py-1 text-xs font-medium transition ${filter === opt.value
                                    ? "bg-dermcare text-white"
                                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                                }`}
                        >
                            {opt.label}
                        </button>
                    ))}
                </div>
            </div>

            {/* Appointments List */}
            {filteredAppointments.length === 0 ? (
                <div className="text-center py-12">
                    <p className="text-4xl mb-3">📭</p>
                    <p className="text-sm text-slate-500">
                        {filter === "ALL" ? "Chưa có lịch hẹn nào" : `Không có lịch hẹn "${FILTER_OPTIONS.find(o => o.value === filter)?.label}"`}
                    </p>
                </div>
            ) : (
                <div className="space-y-3">
                    {filteredAppointments.map(apt => {
                        const status = STATUS_MAP[apt.appointmentStatus] || STATUS_MAP.PENDING;
                        const isUpdating = updatingId === apt.id;

                        return (
                            <div
                                key={apt.id}
                                className={`rounded-xl border p-4 transition hover:shadow-md ${status.bg}`}
                            >
                                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                                    {/* Patient Info */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="text-lg">👤</span>
                                            <p className="font-semibold text-slate-900 truncate">
                                                {apt.patient?.fullName || "Bệnh nhân"}
                                            </p>
                                            <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${status.color} ${status.bg}`}>
                                                {status.label}
                                            </span>
                                        </div>
                                        <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-slate-600">
                                            <span>📅 {formatDate(apt.appointmentDate)}</span>
                                            <span>🕐 {apt.appointmentTime}</span>
                                            {apt.patient?.phone && <span>📞 {apt.patient.phone}</span>}
                                            <span>💰 {formatCurrency(apt.price)}</span>
                                        </div>
                                        {apt.note && (
                                            <p className="mt-1.5 text-xs text-slate-500 italic line-clamp-2">
                                                📝 {apt.note}
                                            </p>
                                        )}
                                    </div>

                                    {/* Action Buttons */}
                                    <div className="flex gap-2 flex-shrink-0">
                                        {apt.appointmentStatus === "PENDING" && (
                                            <>
                                                <button
                                                    onClick={() => handleUpdateStatus(apt.id, "CONFIRMED")}
                                                    disabled={isUpdating}
                                                    className="rounded-lg bg-blue-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-blue-700 transition disabled:opacity-50"
                                                >
                                                    {isUpdating ? "..." : "✓ Xác nhận"}
                                                </button>
                                                <button
                                                    onClick={() => handleUpdateStatus(apt.id, "CANCELLED")}
                                                    disabled={isUpdating}
                                                    className="rounded-lg bg-red-50 border border-red-200 px-3 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-100 transition disabled:opacity-50"
                                                >
                                                    {isUpdating ? "..." : "✗ Từ chối"}
                                                </button>
                                            </>
                                        )}
                                        {apt.appointmentStatus === "CONFIRMED" && (
                                            <button
                                                onClick={() => handleUpdateStatus(apt.id, "COMPLETED")}
                                                disabled={isUpdating}
                                                className="rounded-lg bg-green-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-green-700 transition disabled:opacity-50"
                                            >
                                                {isUpdating ? "..." : "✓ Hoàn thành"}
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}
